  "settings.appearance.desc": "Wähle ein Design für die gesamte App — umfasst Topnav, Seitenleiste, Karten und Akzente. Änderungen werden sofort angewendet.",
  "settings.accent.desc": "Färbe Schaltflächen, Links und aktive Zustände ein, ohne dein Design zu verlieren. Wird beim Zurücksetzen auf den integrierten Akzent zurückgesetzt.",
  "settings.integrations.desc": "Verbinde externe Shop-Konten, um deine gekauften Spiele, Spielzeiten und Erfolge in GameIndex zu importieren.",
  "settings.rockstar.desc": "Scanne installierte Spiele des Rockstar Games Launchers (GTA, Red Dead, Max Payne & mehr) und starte sie über den Rockstar-Client. Kein Konto erforderlich.",
  "settings.rockstar.detected": "Rockstar Games Launcher erkannt",
  "settings.rockstar.notInstalled": "Der Rockstar Games Launcher ist nicht installiert — es können nur bereits installierte Titel erkannt werden.",
  "settings.rockstar.localNote": "Die Erkennung erfolgt vollständig lokal: GameIndex liest die Windows-Deinstallationsregistrierung für installierte Rockstar-Titel.",
  "settings.rockstar.scanBtn": "Installierte Spiele scannen",
  "settings.ubisoft.desc": "Importiere deine Ubisoft Connect-Bibliothek — installierte Spiele und deinen gesamten Katalog — und starte Titel über den Ubisoft Connect-Client. Kein Konto erforderlich.",
  "settings.ubisoft.detected": "Ubisoft Connect erkannt",
  "settings.ubisoft.notInstalled": "Ubisoft Connect ist nicht installiert — es können nur bereits installierte Spiele über die Registrierung erkannt werden.",
  "settings.ubisoft.localNote": "Die Erkennung erfolgt vollständig lokal: GameIndex liest die Windows-Deinstallationsregistrierung für installierte Titel und den Ubisoft Connect-Cache für deine Bibliothek.",
  "settings.ubisoft.syncBtn": "Bibliothek synchronisieren",
  "settings.integrations.footerNotice": "Weitere Integrationen demnächst verfügbar — itch.io und mehr.",
  "settings.autoSync.desc": "Wie oft GameIndex deine Bibliothek im Hintergrund von Steam, Epic und GOG neu importiert.",
  "settings.historyRetention.desc": "Wie lange historische Steam-Spielerzahlen für die Trend-Sparklines auf jeder Spielseite gespeichert werden. Kürzer = weniger Speicherplatz; länger = detailliertere Kurven.",
  "settings.achievements.noSpoilersTitle": "Erfolgsfortschritt ausblenden (keine Spoiler)",
  "settings.achievements.noSpoilersDesc": "Entfernt globale Freischaltprozente und Seltenheitsringe von der Erfolge-Registerkarte und der Spielseite, damit Erfolgslisten wie eine saubere Checkliste wirken.",
  "settings.achievements.localTitle": "Erfolge für heruntergeladene / gecrackte Spiele verfolgen",
  "settings.achievements.localDesc": "Überwacht lokale Erfolgskonfigurationen von Cracks & Emulatoren (Goldberg, CODEX, RUNE, OnlineFix u.v.m.) und schaltet Erfolge für Nicht-Steam-Spiele frei. Erfolgsdetails werden anonym abgerufen.",
  "settings.discord.title": "Zeigen, was du spielst, auf Discord",
  "settings.discord.desc": "Veröffentlicht einen „Spielt X“-Status in deinem Discord-Profil und entfernt ihn beim Beenden des Spiels.",
  "settings.downloads.notifyDesc": "Lasse dich benachrichtigen, wenn ein Download abgeschlossen ist, damit Übertragungen im Hintergrund laufen können.",
  "settings.downloads.bandwidthDesc": "Steuere die maximale Geschwindigkeit beim Herunterladen und Hochladen von Spiel-Torrents.",
  "settings.downloads.blockedCount": "{count} blockierte Domäne{s}",
  "settings.downloads.blockedNone": "Keine Domänen blockiert",
  "settings.downloads.blockedDesc": "Hier aufgelistete Domains werden aus jeder Download-Suche herausgefiltert — nichts von diesen Hosts erscheint in der Ergebnisliste des Download-Modals. Eine Domain pro Zeile.",
  "settings.downloads.sourcesDescStart": "Füge JSON-formatierte Quell-URLs hinzu, um Download-Spiegelserver für deine Spiele zu finden. Quellen verwenden ein kompatibles JSON-Format mit einem",
  "settings.downloads.sourcesDescEnd": "Array und sind registriert. Die Download-Schaltfläche auf jeder Spielseite durchsucht deine aktivierten Quellen.",
  "settings.downloads.debridDesc": "Konfiguriere einen Debrid-Dienst (AllDebrid oder TorBox), um Torrent-Magnet-Links über schnelle direkte HTTP-Verbindungen herunterzuladen.",
  "settings.launcher.desc": "Entscheide, was GameIndex beim Start tut, wenn du ein Spiel startest und wie sich das Fenster selbst verhält.",
  "settings.launcher.autostartFailed": "Autostart konnte nicht aktualisiert werden: {error}",
  "settings.launcher.landingTitle": "Standard-Startseite",
  "settings.launcher.landingDesc": "Welcher Bereich geöffnet wird, wenn GameIndex startet. Nützlich, wenn dein Arbeitsablauf in Aktivität, Downloads oder Angeboten anstatt in der Bibliothek beginnt.",
  "settings.launcher.trayTitle": "In den System-Tray minimieren statt beenden",
  "settings.launcher.trayDesc": "Klicken auf × hält den Launcher im Hintergrund am Laufen. Klicke mit der rechten Maustaste auf das Tray-Symbol, um wirklich zu beenden.",
  "settings.launcher.minimizeTitle": "Minimieren, wenn ein Spiel startet",
